// at-least-once queue; handler charges a card (a side effect)
while (true) {
  const msg = await queue.receive();
  queue.ack(msg);                 // ack first so we don't reprocess
  try {
    await chargeCard(msg.amount, msg.cardId);
  } catch (err) {
    log.error(err);               // swallow and move on
  }
}
